-- Historical event summaries, internal review only; dates taken from cited reports.
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a230-000000000001','history','ĐẠI LỄ KHAI ĐẠO NĂM BÍNH DẦN','Theo bài viết của Hội Thánh, ngày rằm tháng 10 năm Bính Dần (1926) là ngày Khai Đạo Cao Đài.','https://caodai.com.vn/vn/news-detail/ngay-le-khai-dao-nam-thu-88-tai-thanh-that-saigon.html','Hội Thánh Cao Đài Tòa Thánh Tây Ninh – bài hồi cố Đạo sử','15/10/1926 ÂL','Bản tóm lược để Ban Quản trị đối chiếu với sử liệu gốc, xác nhận ngày âm và quyền sử dụng trước khi công bố.','history:https://caodai.com.vn/vn/news-detail/ngay-le-khai-dao-nam-thu-88-tai-thanh-that-saigon.html');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a230-000000000002','history','ĐỨC CHÍ TÔN BAN TỊCH ĐẠO CHO CHỨC SẮC NAM PHÁI','Bài Thuyết Đạo vía Đức Quan Thánh Đế Quân năm 2011 nhắc lại việc ban Tịch Đạo cho Chức Sắc Nam phái vào Tý thời chuyển sang mồng Hai tháng bảy Bính Dần.','https://caodai.com.vn/vn/news-detail/bai-thuyet-dao-via-duc-quan-thanh-de-quan-dl-24-7-2011.html','Hội Thánh Cao Đài Tòa Thánh Tây Ninh – bài hồi cố Đạo sử','02/07/1926 ÂL','Bản tóm lược để Ban Quản trị đối chiếu với sử liệu gốc, xác nhận ngày âm và quyền sử dụng trước khi công bố.','history:https://caodai.com.vn/vn/news-detail/bai-thuyet-dao-via-duc-quan-thanh-de-quan-dl-24-7-2011.html');

-- Editorial historical candidates (paraphrases; pending, no automatic rights or publication).
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000001','history','ĐỨC CHÍ TÔN DẠY HAI VỊ ĐẦU SƯ LO VIỆC KHAI ĐẠO','Đức Chí Tôn giáng cơ truyền dạy hai vị Đầu Sư Thượng Trung Nhựt và Ngọc Lịch Nguyệt triệu tập chư Thánh để lo việc khai Đạo.','','https://mattrankhanhhoa.org.vn/tin-bai/dan-toc-ton-giao/thu-ban-ve-ngay-khai-dao-cua-dao-cao-dai-665','Thử bàn về Ngày khai đạo của đạo Cao đài; dẫn Thánh Ngôn Hiệp Tuyển Q.1, tr.30','1926-09-22','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-09-22:0' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-09-22' AND title='ĐỨC CHÍ TÔN DẠY HAI VỊ ĐẦU SƯ LO VIỆC KHAI ĐẠO');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000002','history','ĐẠI HỘI LẬP TỜ KHAI ĐẠO','Ngài Lê Văn Trung triệu tập chư Đạo hữu để lập danh sách 247 người đứng tên khai Đạo với Chánh phủ.','Địa điểm: Nhà ông Nguyễn Văn Tường, đường Galliéni, Sài Gòn','https://mattrankhanhhoa.org.vn/tin-bai/dan-toc-ton-giao/thu-ban-ve-ngay-khai-dao-cua-dao-cao-dai-665','Thử bàn về Ngày khai đạo của đạo Cao đài; dẫn Đạo Sử Q.II của Hương Hiếu','1926-09-29','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-09-29:1' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-09-29' AND title='ĐẠI HỘI LẬP TỜ KHAI ĐẠO');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000003','history','NỘP TỜ KHAI ĐẠO CHO THỐNG ĐỐC NAM KỲ','Ngài Đầu Sư Thượng Trung Nhựt đem Tờ Khai Đạo trình Thống đốc Le Fol.','Địa điểm: Dinh Thống đốc Nam Kỳ','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_K.htm','Cao Đài Tự Điển, Đức Nguyên, mục Khai Đạo','1926-10-07','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-10-07:2' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-10-07' AND title='NỘP TỜ KHAI ĐẠO CHO THỐNG ĐỐC NAM KỲ');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000004','history','LỄ KỶ NIỆM HAI NĂM LẬP TỜ KHAI ĐẠO','Ngài Đầu Sư Thượng Trung Nhựt tổ chức lễ kỷ niệm hai năm lập Tờ Khai Đạo và đọc bài Thuyết Đạo ôn lại sự kiện.','Địa điểm: Nhà ông Nguyễn Văn Tường','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_K.htm','Cao Đài Tự Điển, Đức Nguyên, mục Khai Đạo','23/8/1928 ÂL','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:23/8/1928 ÂL:3' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='23/8/1928 ÂL' AND title='LỄ KỶ NIỆM HAI NĂM LẬP TỜ KHAI ĐẠO');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000005','history','ĐỨC CHÍ TÔN GIÁNG CƠ DẠY ĐẠO NHƠN DỊP LỄ VÍA','Các môn đệ đầu tiên tề tựu trong đêm lễ vía Đức Chí Tôn; Ngài giáng cơ dạy Đạo.','Địa điểm: Nhà Ngài Vương Quan Kỳ, đường Lagrandière','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_NG.htm','Cao Đài Tự Điển, Đức Nguyên, mục Ngô Văn Chiêu','1926-02-21','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-02-21:4' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-02-21' AND title='ĐỨC CHÍ TÔN GIÁNG CƠ DẠY ĐẠO NHƠN DỊP LỄ VÍA');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000006','history','PHONG THÁNH NỮ PHÁI LẦN THỨ NHỨT','Trong kỳ Phong Thánh Nữ phái đầu tiên, bà Nguyễn Thị Sanh, hiền nội Ngài Trương Hữu Đức, được phong phẩm Nữ Lễ Sanh.','','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_H.htm','Cao Đài Tự Điển, Đức Nguyên, mục H','1927-02-15','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1927-02-15:5' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1927-02-15' AND title='PHONG THÁNH NỮ PHÁI LẦN THỨ NHỨT');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000007','history','BÀ LÂM NGỌC THANH NHẬP MÔN','Bà Lâm Ngọc Thanh được Đức Chí Tôn độ và nhập môn vào Đạo Cao Đài.','','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_N.htm','Cao Đài Tự Điển, Đức Nguyên, mục N','1926-07-16','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-07-16:6' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-07-16' AND title='BÀ LÂM NGỌC THANH NHẬP MÔN');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000008','history','NGÀI CHƯỞNG PHÁP NGUYỄN VĂN TƯƠNG ĐĂNG TIÊN','Ngài Chưởng Pháp Nguyễn Văn Tương thọ bệnh và đăng Tiên tại tư gia, hưởng thọ 48 tuổi.','Địa điểm: Tư gia, làng Hữu Đạo','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_CH.htm','Cao Đài Tự Điển, Đức Nguyên, mục CH; dẫn Đạo Sử Q.2, tr.218','1926-12-11','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-12-11:7' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-12-11' AND title='NGÀI CHƯỞNG PHÁP NGUYỄN VĂN TƯƠNG ĐĂNG TIÊN');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) SELECT 'f17f8dc1-e43b-4dd3-a240-000000000009','history','ĐỨC CHÍ TÔN DẠY MAY ĐẠO PHỤC GIÁO TÔNG','Đức Chí Tôn dạy ba vị Lê Văn Trung, Cao Quỳnh Cư và Phạm Công Tắc đến nhà Ngài Ngô Văn Chiêu truyền lời may bộ Đạo phục Giáo Tông.','','https://caodaiebook.net/CaoDaiTuDien(v2012)/cdtd-van_G.htm','Cao Đài Tự Điển, Đức Nguyên, mục Giáo Tông','1926-04-17','Tóm lược biên tập từ nguồn điện tử, cần đối chiếu nguyên bản, niên đại, địa điểm và quyền sử dụng.','history-editorial:1926-04-17:8' WHERE NOT EXISTS(SELECT 1 FROM gdd_research_items WHERE kind='history' AND source_date='1926-04-17' AND title='ĐỨC CHÍ TÔN DẠY MAY ĐẠO PHỤC GIÁO TÔNG');
